export function validateNativeProfileProposal(value: unknown, snapshot: InspectionSnapshot): NativeProfileProposal {
  const proposed = structuredClone(value) as NativeProfileProposal;
  if (!proposed || !proposed.profile || Object.keys(proposed).some(key => !['profile','auditPaths'].includes(key))) throw new Error('Supply a profile and explicit fixture audit starting paths.');
  const profile = proposed.profile;
  if (Object.keys(profile).some(key => !['id','build','launchArguments','fixtureExpectedDataRoot','bundleIdentifier'].includes(key)) || !/^[A-Za-z0-9_-]{1,64}$/.test(profile.id)) throw new Error('Invalid proposed native profile. Audit receipts are issued only by the service.');
  profile.build = parseAppleCheckCommand(`${APPLE_CHECK_PREFIX} ${JSON.stringify(profile.build)}`);
  if (profile.build.tool !== 'xcodebuild') throw new Error('Native app setup requires a fixed xcodebuild recipe.');
  if (!snapshot.manifest.roots[0]?.entries.some(entry => entry.path.startsWith(`${profile.build.tool === 'xcodebuild' ? profile.build.project : ''}/`))) throw new Error('The proposed Xcode project is absent from the captured primary source.');
  if (!Array.isArray(profile.launchArguments) || !profile.launchArguments.length || profile.launchArguments.length > 32 || profile.launchArguments.some(arg => typeof arg !== 'string' || arg.length > 4096 || /[\0\r\n]/.test(arg)) || !profile.launchArguments.some(arg => arg.includes('{runId}'))) throw new Error('Fixture arguments need an explicit unique {runId} namespace.');
  if (profile.bundleIdentifier !== undefined && !/^[A-Za-z0-9][A-Za-z0-9.-]+$/.test(profile.bundleIdentifier)) throw new Error('Invalid product bundle identity.');
  if (profile.build.platform === 'macos' && (!profile.fixtureExpectedDataRoot || !/^\/(?:private\/)?tmp\/enoughfactory-fixtures\/\{runId\}(?:\/[A-Za-z0-9._-]+)*$/.test(profile.fixtureExpectedDataRoot) || profile.fixtureExpectedDataRoot.split('/').some(part=>part==='.'||part==='..'))) throw new Error('Mac fixture storage must be a fresh /tmp/enoughfactory-fixtures/{runId} namespace.');
  if (profile.build.platform === 'ios-simulator' && profile.fixtureExpectedDataRoot !== undefined) throw new Error('iPhone fixtures use their owned Simulator app sandbox; omit a host data-root expectation and audit the in-app run namespace.');
  if (!Array.isArray(proposed.auditPaths) || !proposed.auditPaths.length || proposed.auditPaths.length > 128) throw new Error('Supply bounded source audit starting paths.');
  const covered = new Set<Purpose>(), seen = new Set<string>();
  for (const hint of proposed.auditPaths) {
    const root = snapshot.manifest.roots.find(root => root.id === hint.rootId), entry = root?.entries.find(entry => entry.path === hint.path);
    if (!safePath(hint.path) || entry?.kind !== 'file' || seen.has(`${hint.rootId}/${hint.path}`) || !Array.isArray(hint.purposes) || !hint.purposes.length || hint.purposes.some(purpose => !purposes.includes(purpose))) throw new Error('Audit starting paths must be unique original files in declared source roots.');
    seen.add(`${hint.rootId}/${hint.path}`); for (const purpose of hint.purposes) covered.add(purpose);
  }
  if (purposes.some(purpose => !covered.has(purpose))) throw new Error('Identify fixture entry, storage, credentials, providers, preferences, notifications and build starting paths, including explicit disabled paths.');
  return proposed;
}

